// НЕ ПРОВЕРЕН В ЖИВОМ БРАУЗЕРЕ: блокировка Hebcal через page.route была недоступна при генерации; написан строго по плану.
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

test.describe('זמני היום', () => {
  test('ZM-06 Источник זמנים (Hebcal) недоступен → явное сообщение, без примерного времени; молитва и תהילים работают #6a86f800 @prod-safe @mobile', async ({ page }) => {
    // 1. До перехода: заблокировать Hebcal; увеличить таймаут.
    test.setTimeout(90_000);
    const handler = (route: import('@playwright/test').Route) => route.abort();
    await page.route('**/www.hebcal.com/**', handler);

    // 2. Открыть `/zmanim` и дождаться текста «זמני היום אינם זמינים כרגע.».
    await page.goto('/zmanim');
    await expect(page.getByText('זמני היום אינם זמינים כרגע.')).toBeVisible({ timeout: 45_000 });
    await expect(page.getByText('לא מוצג זמן משוער.')).toBeVisible();
    await expect(page.getByText('הלימוד היומי אינו זמין כרגע.')).toBeVisible({ timeout: 45_000 });
    await expect(page.getByText('נסו שוב')).toHaveCount(2);
    await expect(page.getByText(/\b\d{1,2}:\d{2}\b/)).toHaveCount(0);
    await expect(page.locator('#zmanim-hebrew-date')).toBeVisible();
    await expect(page.locator('#zmanim-source')).toContainText('Hebcal');
    await expect(page.locator('#zmanim-methods-unapproved')).toContainText('טרם אושרו');

    // 3. Не снимая блокировку, открыть `/prayer/mincha_ashkenaz`, затем `/tehilim`.
    await page.goto('/prayer/mincha_ashkenaz');
    await expect(page.getByRole('heading', { level: 1, name: 'מנחה (אשכנזי)' })).toBeVisible();
    await expect(page.getByText(/\d+ מתוך \d+/).first()).toBeVisible();
    await page.goto('/tehilim');
    await expect(page.getByRole('heading', { level: 1 }).first()).toBeVisible();

    // 4. Снять блокировку.
    await page.unroute('**/www.hebcal.com/**', handler);
  });
});
